(function() {
    'use strict';

    class HotelRevenueAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Hotel Revenue Maximizer';
            this.version = '1.1.0';

            this.TOTAL_ROOMS = 200;
            this.DAYS_PER_MONTH = 30;
            this.AVAILABLE_ROOM_NIGHTS = 200 * 30;
            this.BASE_ADR = 112;
            this.BASE_FIXED_COSTS = 120000;
            this.VARIABLE_COST_PER_RN = 35;
            this.OTA_COMMISSION_RATE = 0.18;
            this.DIRECT_COST_PER_RN = 4;

            this.ROUNDS = [
                {
                    month: 'January', monthEs: 'Enero', season: 'Low', baseDemandRate: 0.48,
                    competitorADR: 105, competitorOcc: 46,
                    briefing: 'Low season begins. Post-holiday occupancy is soft across the market. Corporate contracts are being renewed for the year. A good time to invest in loyalty and build your direct booking base.',
                    briefingEs: 'Temporada baja. La ocupación post-vacacional es débil en todo el mercado. Los contratos corporativos se están renovando. Buen momento para invertir en lealtad y construir reservas directas.',
                    groupOffer: { rooms: 25, nights: 3, rate: 85, fbRevenue: 2100, desc: 'Regional sales team retreat: 25 rooms for 3 nights at $85/night. Includes breakfast meetings.', descEs: 'Retiro de equipo de ventas regional: 25 habitaciones por 3 noches a $85/noche. Incluye desayunos de trabajo.' }
                },
                {
                    month: 'February', monthEs: 'Febrero', season: 'Low', baseDemandRate: 0.52,
                    competitorADR: 108, competitorOcc: 49,
                    briefing: 'Still low season but a Valentine weekend spike is expected. Leisure packages and F&B promotions can capture incremental revenue. OTA visibility matters for impulse bookings.',
                    briefingEs: 'Sigue temporada baja pero se espera un pico por San Valentín. Los paquetes de ocio y promociones de F&B pueden captar ingresos incrementales.',
                    groupOffer: { rooms: 30, nights: 2, rate: 95, fbRevenue: 3600, desc: 'Wedding celebration block: 30 rooms for 2 nights at $95/night. Strong F&B revenue from reception.', descEs: 'Bloque de boda: 30 habitaciones por 2 noches a $95/noche. Fuerte ingreso de F&B por la recepción.' }
                },
                {
                    month: 'March', monthEs: 'Marzo', season: 'Shoulder', baseDemandRate: 0.60,
                    competitorADR: 110, competitorOcc: 56,
                    briefing: 'Shoulder season begins. Spring break leisure demand is rising, and early corporate travel is picking up. Test your rate elasticity — this is a good month to experiment with pricing.',
                    briefingEs: 'Comienza temporada media. La demanda de ocio por vacaciones de primavera sube y los viajes corporativos arrancan. Buen mes para experimentar con precios.',
                    groupOffer: { rooms: 40, nights: 4, rate: 78, fbRevenue: 2400, desc: 'University study group: 40 rooms for 4 nights at $78/night. Budget-conscious but high volume.', descEs: 'Grupo universitario: 40 habitaciones por 4 noches a $78/noche. Presupuesto ajustado pero alto volumen.' }
                },
                {
                    month: 'April', monthEs: 'Abril', season: 'Shoulder', baseDemandRate: 0.62,
                    competitorADR: 112, competitorOcc: 58,
                    briefing: 'Easter holidays drive leisure demand. Families and international visitors are arriving. Package optimization and channel mix are key decisions this month.',
                    briefingEs: 'Las vacaciones de Semana Santa impulsan la demanda de ocio. Llegan familias y visitantes internacionales. La optimización de paquetes y mix de canales son clave.',
                    groupOffer: { rooms: 35, nights: 3, rate: 82, fbRevenue: 2800, desc: 'Easter tour operator block: 35 rooms for 3 nights at $82/night. Includes half-board package.', descEs: 'Bloque de tour operador de Semana Santa: 35 habitaciones por 3 noches a $82/noche. Incluye media pensión.' }
                },
                {
                    month: 'May', monthEs: 'Mayo', season: 'Strong', baseDemandRate: 0.78,
                    competitorADR: 125, competitorOcc: 72,
                    briefing: 'Major business conference in the city with 1,200 delegates. Corporate transient demand surges. Rate discipline is critical — this is when revenue managers earn their keep. Protect your high-rate inventory.',
                    briefingEs: 'Gran conferencia de negocios en la ciudad con 1,200 delegados. La demanda corporativa transitoria se dispara. La disciplina de tarifas es crítica. Proteja su inventario de tarifas altas.',
                    groupOffer: { rooms: 50, nights: 5, rate: 105, fbRevenue: 7500, desc: 'Conference overflow: 50 rooms for 5 nights at $105/night. This is a displacement decision — high-paying transient guests may book these dates.', descEs: 'Desbordamiento de conferencia: 50 habitaciones por 5 noches a $105/noche. Decisión de desplazamiento — huéspedes transitorios de alta tarifa podrían reservar estas fechas.' }
                },
                {
                    month: 'June', monthEs: 'Junio', season: 'Moderate', baseDemandRate: 0.65,
                    competitorADR: 118, competitorOcc: 62,
                    briefing: 'School year ends and family travel begins. Moderate demand with a mix of segments. A transitional month — invest in positioning for the upcoming high season.',
                    briefingEs: 'Termina el año escolar y comienzan los viajes familiares. Demanda moderada con mezcla de segmentos. Mes de transición — invierta en posicionamiento para la temporada alta.',
                    groupOffer: { rooms: 20, nights: 5, rate: 92, fbRevenue: 2000, desc: 'Corporate training retreat: 20 rooms for 5 nights at $92/night. Meeting room included.', descEs: 'Retiro de capacitación corporativa: 20 habitaciones por 5 noches a $92/noche. Salón de reuniones incluido.' }
                },
                {
                    month: 'July', monthEs: 'Julio', season: 'High', baseDemandRate: 0.85,
                    competitorADR: 135, competitorOcc: 80,
                    briefing: 'Peak leisure season. Maximum rate discipline is essential — close low-rate tiers and enforce minimum length of stay. Every room sold below potential is lost revenue forever.',
                    briefingEs: 'Temporada alta de ocio. La disciplina máxima de tarifas es esencial — cierre niveles de tarifa baja y aplique estadía mínima. Cada habitación vendida por debajo del potencial es ingreso perdido para siempre.',
                    groupOffer: { rooms: 45, nights: 7, rate: 88, fbRevenue: 4500, desc: 'Travel agency summer block: 45 rooms for 7 nights at $88/night. High volume but well below peak transient rates.', descEs: 'Bloque de verano de agencia de viajes: 45 habitaciones por 7 noches a $88/noche. Alto volumen pero muy por debajo de tarifas transitorias de temporada alta.' }
                },
                {
                    month: 'August', monthEs: 'Agosto', season: 'High', baseDemandRate: 0.87,
                    competitorADR: 138, competitorOcc: 83,
                    briefing: 'Continued peak season with strong international arrivals. Optimize revenue per square meter across all departments — spa, F&B, and events. Service quality matters: overcrowding damages satisfaction.',
                    briefingEs: 'Continúa la temporada alta con fuertes llegadas internacionales. Optimice ingresos por metro cuadrado en todos los departamentos. La calidad del servicio importa: el hacinamiento daña la satisfacción.',
                    groupOffer: { rooms: 55, nights: 5, rate: 80, fbRevenue: 5000, desc: 'International tour operator: 55 rooms for 5 nights at $80/night. Large block at discounted rate during your peak season.', descEs: 'Tour operador internacional: 55 habitaciones por 5 noches a $80/noche. Bloque grande a tarifa descontada durante su temporada alta.' }
                },
                {
                    month: 'September', monthEs: 'Septiembre', season: 'Shoulder', baseDemandRate: 0.72,
                    competitorADR: 120, competitorOcc: 68,
                    briefing: 'A new 150-room Marriott Courtyard has opened in the market, adding 15% capacity to the competitive set. Properties without strong brand differentiation and direct booking bases will feel immediate pressure. Adapt your strategy.',
                    briefingEs: 'Un nuevo Marriott Courtyard de 150 habitaciones ha abierto en el mercado, añadiendo 15% de capacidad al set competitivo. Las propiedades sin fuerte diferenciación de marca sentirán presión inmediata. Adapte su estrategia.',
                    groupOffer: { rooms: 30, nights: 4, rate: 98, fbRevenue: 3000, desc: 'Tech company offsite: 30 rooms for 4 nights at $98/night. Meeting facilities and team dinners required.', descEs: 'Encuentro de empresa tech: 30 habitaciones por 4 noches a $98/noche. Requiere salones de reunión y cenas de equipo.' }
                },
                {
                    month: 'October', monthEs: 'Octubre', season: 'Strong', baseDemandRate: 0.76,
                    competitorADR: 128, competitorOcc: 71,
                    briefing: 'Second major business conference of the year. Strong dual-segment demand from both business and autumn leisure travelers. Group displacement decisions are critical this month.',
                    briefingEs: 'Segunda gran conferencia de negocios del año. Fuerte demanda dual de negocios y viajeros de ocio otoñal. Las decisiones de desplazamiento de grupos son críticas este mes.',
                    groupOffer: { rooms: 60, nights: 4, rate: 110, fbRevenue: 8400, desc: 'Conference delegation: 60 rooms for 4 nights at $110/night. Premium group with strong F&B spend. Largest group offer of the year.', descEs: 'Delegación de conferencia: 60 habitaciones por 4 noches a $110/noche. Grupo premium con fuerte gasto en F&B. La mayor oferta grupal del año.' }
                },
                {
                    month: 'November', monthEs: 'Noviembre', season: 'Shoulder', baseDemandRate: 0.60,
                    competitorADR: 115, competitorOcc: 57,
                    briefing: 'Corporate year-end travel and early holiday leisure. Demand is softening but December advance purchase promotions can capture forward revenue. Think about your pricing for the holiday season.',
                    briefingEs: 'Viajes corporativos de fin de año y ocio navideño temprano. La demanda se suaviza pero las promociones anticipadas de diciembre pueden captar ingresos futuros.',
                    groupOffer: { rooms: 25, nights: 3, rate: 90, fbRevenue: 1800, desc: 'Government workshop: 25 rooms for 3 nights at $90/night. Standard rate, minimal F&B.', descEs: 'Taller gubernamental: 25 habitaciones por 3 noches a $90/noche. Tarifa estándar, F&B mínimo.' }
                },
                {
                    month: 'December', monthEs: 'Diciembre', season: 'Mixed', baseDemandRate: 0.67,
                    competitorADR: 122, competitorOcc: 63,
                    briefing: 'Final month. Holiday leisure demand is strong but corporate shutdowns reduce business segment. Segment mix management is essential. End the year with strong RevPAR and satisfaction scores.',
                    briefingEs: 'Último mes. La demanda de ocio navideño es fuerte pero el cierre corporativo reduce el segmento de negocios. La gestión del mix de segmentos es esencial. Cierre el año con fuerte RevPAR y satisfacción.',
                    groupOffer: { rooms: 40, nights: 2, rate: 100, fbRevenue: 6000, desc: 'Holiday gala and year-end celebration: 40 rooms for 2 nights at $100/night. Premium F&B event attached.', descEs: 'Gala navideña y celebración de fin de año: 40 habitaciones por 2 noches a $100/noche. Evento premium de F&B adjunto.' }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 500000,
                    satisfaction: 4.1,
                    directBookingRate: 0.24,
                    totalRoomRevenue: 0,
                    totalGop: 0,
                    cumulativeRevpar: 0,
                    revparHistory: [],
                    gopparHistory: [],
                    occupancyHistory: [],
                    satisfactionHistory: [],
                    adrHistory: [],
                    netRevparHistory: [],
                    trevparHistory: [],
                    revparIndexHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    adr: 112,
                    otaPct: 58,
                    marketingBudget: 3000,
                    serviceInvestment: 5000,
                    groupAccept: true
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var adrInput = document.getElementById('adrInput');
            if (adrInput) decisions.adr = parseFloat(adrInput.value);

            var otaInput = document.getElementById('otaInput');
            if (otaInput) decisions.otaPct = parseFloat(otaInput.value);

            var marketingInput = document.getElementById('marketingInput');
            if (marketingInput) decisions.marketingBudget = parseFloat(marketingInput.value);

            var serviceInput = document.getElementById('serviceInput');
            if (serviceInput) decisions.serviceInvestment = parseFloat(serviceInput.value);

            var groupSelect = document.getElementById('groupSelect');
            if (groupSelect) decisions.groupAccept = (groupSelect.value === 'accept');

            if (!decisions.adr || decisions.adr < 60 || decisions.adr > 250) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('adr_warning'), 'warning'
                );
                return false;
            }

            if (decisions.otaPct === undefined || decisions.otaPct < 0 || decisions.otaPct > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('ota_warning'), 'warning'
                );
                return false;
            }

            if (decisions.marketingBudget === undefined || decisions.marketingBudget < 0 || decisions.marketingBudget > 20000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('marketing_warning'), 'warning'
                );
                return false;
            }

            if (decisions.serviceInvestment === undefined || decisions.serviceInvestment < 0 || decisions.serviceInvestment > 20000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('service_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var monthIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[monthIdx];
            var arn = this.AVAILABLE_ROOM_NIGHTS;

            // Group booking
            var groupRN = 0;
            var groupRevenue = 0;
            var groupFbRevenue = 0;
            if (d.groupAccept && round.groupOffer) {
                groupRN = round.groupOffer.rooms * round.groupOffer.nights;
                groupRevenue = groupRN * round.groupOffer.rate;
                groupFbRevenue = round.groupOffer.fbRevenue || 0;
            }

            var remainingRN = arn - groupRN;

            // Price elasticity
            var priceEffect = Math.pow(this.BASE_ADR / d.adr, 1.2);
            priceEffect = Math.max(0.4, Math.min(1.6, priceEffect));

            // Satisfaction multiplier
            var satMultiplier = 1 + (ds.satisfaction - 4.0) * 0.25;

            // OTA billboard effect
            var otaBillboard = 1 + (d.otaPct / 100 - 0.30) * 0.12;
            otaBillboard = Math.max(0.85, Math.min(1.15, otaBillboard));

            // Direct booking demand bonus from accumulated loyalty investment
            var directBonus = 1 + (ds.directBookingRate - 0.24) * 0.15;

            // Competitive shock from Month 9 onward (new Marriott)
            var compShock = monthIdx >= 8 ? 0.88 : 1.0;
            // Mitigate shock if satisfaction is high
            if (monthIdx >= 8 && ds.satisfaction >= 4.3) {
                compShock += (ds.satisfaction - 4.3) * 0.10;
                compShock = Math.min(compShock, 0.97);
            }

            // Total demand multiplier
            var demandMultiplier = priceEffect * satMultiplier * otaBillboard * directBonus * compShock;

            // Stochastic noise (+/- 8%)
            var noise = 1 + (Math.random() - 0.5) * 0.16;
            demandMultiplier *= noise;

            // Base transient demand
            var baseTransientDemand = round.baseDemandRate * arn;
            var adjustedDemand = Math.round(baseTransientDemand * demandMultiplier);

            // Actual transient room nights
            var transientRN = Math.min(adjustedDemand, remainingRN);
            transientRN = Math.max(0, transientRN);

            // Total room nights
            var totalRN = transientRN + groupRN;
            var occupancyRate = totalRN / arn;

            // Revenue
            var transientRoomRevenue = transientRN * d.adr;
            var totalRoomRevenue = transientRoomRevenue + groupRevenue;

            // Blended ADR
            var blendedADR = totalRN > 0 ? totalRoomRevenue / totalRN : 0;

            // RevPAR
            var revpar = totalRoomRevenue / arn;

            // Distribution costs
            var otaFraction = d.otaPct / 100;
            var otaRN = Math.round(transientRN * otaFraction);
            var directRN = transientRN - otaRN;
            var otaCommission = otaRN * d.adr * this.OTA_COMMISSION_RATE;
            var directCost = directRN * this.DIRECT_COST_PER_RN;
            var totalDistCost = otaCommission + directCost;

            // Net room revenue and Net RevPAR
            var netRoomRevenue = totalRoomRevenue - totalDistCost;
            var netRevpar = netRoomRevenue / arn;

            // F&B and ancillary revenue
            var fbPerOccRoom = 28 * (1 + (ds.satisfaction - 4.0) * 0.15);
            var fbRevenue = Math.round(totalRN * fbPerOccRoom) + groupFbRevenue;

            // TRevPAR
            var trevpar = (totalRoomRevenue + fbRevenue) / arn;

            // Operating costs
            var variableCosts = totalRN * this.VARIABLE_COST_PER_RN;
            var totalCosts = this.BASE_FIXED_COSTS + variableCosts + totalDistCost + d.marketingBudget + d.serviceInvestment;

            // GOP and GOPPAR
            var gop = totalRoomRevenue + fbRevenue - totalCosts;
            var goppar = gop / arn;

            // Update satisfaction (partial lag)
            var satChange = (d.serviceInvestment - 5000) / 55000;
            // Overcrowding penalty
            if (occupancyRate > 0.90) {
                satChange -= (occupancyRate - 0.90) * 0.6;
            }
            // Small random factor
            satChange += (Math.random() - 0.5) * 0.04;
            ds.satisfaction = Math.max(3.0, Math.min(5.0,
                Math.round((ds.satisfaction + satChange) * 100) / 100));

            // Update direct booking rate (lagged effect of marketing)
            var directBoost = (d.marketingBudget / 120000) * 0.025;
            // Natural decay toward OTA dependency if not investing
            var directDecay = d.marketingBudget < 2000 ? 0.008 : 0.002;
            ds.directBookingRate = Math.max(0.10, Math.min(0.70,
                Math.round((ds.directBookingRate + directBoost - directDecay) * 1000) / 1000));

            // Accumulate totals
            ds.cash += Math.round(gop);
            ds.totalRoomRevenue += Math.round(totalRoomRevenue);
            ds.totalGop += Math.round(gop);

            // Push to history arrays
            ds.revparHistory.push(Math.round(revpar * 100) / 100);
            ds.gopparHistory.push(Math.round(goppar * 100) / 100);
            ds.occupancyHistory.push(Math.round(occupancyRate * 1000) / 10);
            ds.satisfactionHistory.push(ds.satisfaction);
            ds.adrHistory.push(Math.round(blendedADR * 100) / 100);
            ds.netRevparHistory.push(Math.round(netRevpar * 100) / 100);

            // Competitor RevPAR for index calculation
            var compRevpar = round.competitorADR * (round.competitorOcc / 100);
            var revparIndex = compRevpar > 0 ? Math.round((revpar / compRevpar) * 100) : 100;

            // v1.1.0 fix: track TRevPAR & RPI, then persist composite where Express reporting reads it.
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            ds.trevparHistory.push(Math.round(trevpar * 100) / 100);
            ds.revparIndexHistory.push(revparIndex);
            var composite = this._crmi(ds.revparHistory, ds.netRevparHistory, ds.satisfactionHistory, ds.revparIndexHistory, ds.trevparHistory).crmi;
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== 'object') ds.performance = {};
            ds.performance.overallScore = composite;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                occupancy: Math.round(occupancyRate * 1000) / 10,
                adr: Math.round(blendedADR * 100) / 100,
                revpar: Math.round(revpar * 100) / 100,
                netRevpar: Math.round(netRevpar * 100) / 100,
                trevpar: Math.round(trevpar * 100) / 100,
                goppar: Math.round(goppar * 100) / 100,
                gop: Math.round(gop),
                roomRevenue: Math.round(totalRoomRevenue),
                fbRevenue: Math.round(fbRevenue),
                distCost: Math.round(totalDistCost),
                satisfaction: ds.satisfaction,
                directRate: ds.directBookingRate,
                revparIndex: revparIndex,
                groupAccepted: d.groupAccept,
                groupRN: groupRN,
                transientRN: transientRN,
                cash: Math.round(ds.cash)
            };
        }

