            var beat = !!s.beatMarket;
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var badgeClass = beat ? 'hrm-cm-badge-pass' : 'hrm-cm-badge-miss';
            var badgeText = beat ? t('cm_badge_beat') : t('cm_badge_missed');
