                    insight_solid:       `Gestión sólida en general. Enfóquese en construir ventajas competitivas para el próximo año.`,
                    cm_score_label:      `Índice Compuesto de Revenue Management`,
                    cm_revpar_label:     `RevPAR Promedio`,
                    cm_goppar_label:     `GOPPAR Promedio`,
                    cm_rpi_label:        `Índice RevPAR Promedio`,
                    cm_sat_label:        `Puntuación Promedio`,
                    cm_insights_title:   `Conclusiones Clave`,
                    cm_badge_beat:       `Sobre el Mercado — Buen Desempeño`,
                    cm_badge_missed:     `Bajo el Mercado — Margen de Mejora`,
                    cm_footer:           `Simulación Hotel Revenue Maximizer completada.`
                }
            };
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            // Detect language
            var lang = 'en';
            try {
                if (window.mySimulation && window.mySimulation.options && window.mySimulation.options.language) {
                    lang = window.mySimulation.options.language;
                } else {
                    var htmlLang = document.documentElement.lang;
                    if (htmlLang && htmlLang.substring(0, 2) === 'es') lang = 'es';
                }
            } catch(e) {}

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var seasonTag = '<strong>' + round.season + ' Season</strong> — ';
                if (lang === 'es') {
                    var seasonMap = { 'Low': 'Baja', 'Shoulder': 'Media', 'Moderate': 'Moderada', 'Strong': 'Alta', 'High': 'Alta', 'Mixed': 'Mixta' };
                    seasonTag = '<strong>Temporada ' + (seasonMap[round.season] || round.season) + '</strong> — ';
                    briefEl.innerHTML = seasonTag + round.briefingEs;
                } else {
                    briefEl.innerHTML = seasonTag + round.briefing;
                }
            }

            var groupPanel = document.getElementById('groupOfferPanel');
            var groupText = document.getElementById('groupOfferText');
            if (groupPanel && groupText && round.groupOffer) {
                groupPanel.style.display = 'block';
                var offer = round.groupOffer;
                var revenueEst = offer.rooms * offer.nights * offer.rate + offer.fbRevenue;
                var offerDesc = lang === 'es' ? offer.descEs : offer.desc;
                groupText.innerHTML = offerDesc + '<br><strong>' +
                    (lang === 'es' ? 'Ingreso estimado' : 'Estimated revenue') +
                    ': $' + revenueEst.toLocaleString() + '</strong>';
            }

            var compPanel = document.getElementById('compIntelText');
            if (compPanel) {
                if (lang === 'es') {
                    compPanel.innerHTML = 'Set competitivo del mes anterior: ADR promedio <strong>$' +
                        round.competitorADR + '</strong> | Ocupación promedio <strong>' +
                        round.competitorOcc + '%</strong> | RevPAR del set: <strong>$' +
                        Math.round(round.competitorADR * round.competitorOcc / 100) + '</strong>';
                } else {
                    compPanel.innerHTML = 'Prior month competitive set: Avg ADR <strong>$' +
                        round.competitorADR + '</strong> | Avg Occupancy <strong>' +
                        round.competitorOcc + '%</strong> | Set RevPAR: <strong>$' +
                        Math.round(round.competitorADR * round.competitorOcc / 100) + '</strong>';
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new HotelRevenueAdapter(), {
            simulationType: 'hotel_revenue_maximizer',
            maxPeriods: 12,
            autoSaveInterval: 30000
        });
    });

})();
